import{_ as a,o as t,c as i,ae as o}from"./chunks/framework.B2ul6ABY.js";const h=JSON.parse('{"title":"Decisions & Deferred Items","description":"","frontmatter":{},"headers":[],"relativePath":"design/decisions.md","filePath":"design/decisions.md"}'),n={name:"design/decisions.md"};function s(r,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="decisions-deferred-items" tabindex="-1">Decisions &amp; Deferred Items <a class="header-anchor" href="#decisions-deferred-items" aria-label="Permalink to &quot;Decisions &amp; Deferred Items&quot;">​</a></h1><blockquote><p>Canonical design document consolidated from <code>docs/design/decisions.md</code> during Stage 22. Stage 23 will reconcile detailed source anchors where needed.</p></blockquote><p>This document records architectural decisions and items explicitly deferred from the initial design.</p><hr><h2 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h2><ol><li><p><strong>Card templates</strong>: No templates for now. Cards are created from scratch by the analyst or planner.</p></li><li><p><strong>Parallelism</strong>: Execution is sequential by default — one planner, executor, or reviewer runs at a time. The analyst is the only always-available concurrent agent. Optional parallel dispatch is deferred.</p></li><li><p><strong>Card editing</strong>: Cards can be edited while in <code>drafting</code> or <code>backlog</code>. Once <code>active</code> or beyond, changes are expressed as notes/directives, or by cancelling and restarting the card.</p></li><li><p><strong>Notification granularity</strong>: Notify on goal completion, goal failure, and escalation by default. Configurable via notification filters (see <code>configuration.md §Notifications</code>).</p></li><li><p><strong>Budget tracking</strong>: Not required for now.</p></li><li><p><strong>Operational work</strong>: No separate functional/operational category. Operational work uses <code>Ops</code> terminal cards or ordinary goals containing <code>Ops</code> cards. Operational goals still require a plan card and passing review — no special treatment.</p></li><li><p><strong>Artifact cleanup policy</strong>: Keep the <code>retain</code> flag on artifacts but do not define an automatic cleanup policy beyond the safety rules in <code>data-model.md §Cleanup Policy</code>.</p></li><li><p><strong>Attachment rendering</strong>: Attachments (inline images, charts, HTML reports) render only in the web UI. Telegram can link to the card or notify that attachments exist, but does not render them inline.</p></li><li><p><strong>Plan diary format</strong>: Planner diary entries are stored as structured JSON. Rendered as Markdown on the fly in the UI and chat.</p></li><li><p><strong>Recursion depth limit</strong>: Configurable maximum goal depth (default: 5 levels). The planner receives current depth and max depth in context and must plan within that limit.</p></li><li><p><strong>Findings dossier split</strong>: <code>audit-findings/</code> and <code>ui-findings/</code> remain separate instead of being merged under a new <code>findings/</code> parent. The source-vs-documentation audit findings and the operator-surface Playwright findings have different provenance, numbering schemes, README remediation logs, and stage ownership; preserving the split avoids broad path churn while keeping both dossiers directly navigable from their existing roots.</p></li></ol><hr><h2 id="persistence-model" tabindex="-1">Persistence Model <a class="header-anchor" href="#persistence-model" aria-label="Permalink to &quot;Persistence Model&quot;">​</a></h2><p>All data is stored as files on the local filesystem. There is no external database.</p><ul><li><strong><code>.saivage/</code></strong>: Persistent project metadata and state: <code>project.json</code>, <code>saivage.json</code>, <code>auth-profiles.json</code>, card records, plan diaries, notes, agent sessions, runtime state, skills, instructions, and indexes.</li><li><strong><code>.saivage-work/</code></strong>: Generated work products and disposable or retainable outputs: artifacts, attachments, process logs, downloads, stash, quarantine payloads, uploads, previews, and temporary runtime files.</li></ul><p>The authoritative schemas and file tree are defined in <code>data-model.md</code>.</p><hr><h2 id="web-ui" tabindex="-1">Web UI <a class="header-anchor" href="#web-ui" aria-label="Permalink to &quot;Web UI&quot;">​</a></h2><p>The web UI is a <strong>card-centric control room</strong> for supervising the autonomous runtime. The detailed UX layout, navigation, section composition, and visual design are defined in <code>docs/design/ux-design.md</code>.</p><p>Key principles:</p><ul><li>A <strong>left rail</strong> provides section navigation (Dashboard, Cards, Agents, Files, Debug).</li><li>The <strong>Dashboard</strong> combines the analyst chat stream and a runtime status panel.</li><li>The <strong>Cards</strong> section is the primary workspace: tree view, board, leaderboard, and timeline over the card model.</li><li>The <strong>Agents</strong> section shows agent conversations and tool traces.</li><li>The <strong>Files</strong> section browses <code>.saivage/</code> metadata and <code>.saivage-work/</code> outputs.</li><li>The <strong>Debug</strong> section exposes runtime state, errors, and timeline.</li></ul><p>Cards created via the web UI go through the analyst agent for structuring (same flow as Telegram or CLI).</p>',17)])])}const u=a(n,[["render",s]]);export{h as __pageData,u as default};
